@Test
void malformedToolCallsRemainObservable() throws Exception {
    var script = MAPPER.readTree("""
            {"responseId":"x","steps":[{"type":"malformed_tool_call","name":"read","argumentsText":"{"}],
             "usage":{"inputTokens":0,"outputTokens":0,"costMicros":0}}
            """);
    var provider = new FauxProvider(
            new DynamicClock(Instant.EPOCH, ZoneOffset.UTC),
            new FixedIdGenerator(List.of("chunk-1")));
    var response = provider.execute(script, ignored -> {}, () -> false);
    assertEquals("malformed_tool_call", response.chunks().getFirst().type());
    assertTrue(response.chunks().getFirst().value().endsWith(":" + "{"));
}

@Test
void scriptedErrorsExposeStableCodeAndRetryDelay() throws Exception {
    var script = MAPPER.readTree("""
            {"responseId":"x","steps":[{"type":"error","code":"provider.rate_limited","retryAfterMillis":250}],
             "usage":{"inputTokens":0,"outputTokens":0,"costMicros":0}}
            """);
    var provider = new FauxProvider(
            new DynamicClock(Instant.EPOCH, ZoneOffset.UTC),
            new FixedIdGenerator(List.of()));
    var error = assertThrows(FauxProvider.FauxProviderException.class,
            () -> provider.execute(script, ignored -> {}, () -> false));
    assertEquals("provider.rate_limited", error.code());
    assertEquals(250, error.retryAfterMillis());
}

